// Package regsync holds the synchronized registry entry lists and network tags
// sent during the configuration phase. The data is generated by tools/syncgen.
package regsync

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"strings"
	"sync"
)

//go:embed sync.json.gz
var blob []byte

type Registry struct {
	Name    string
	Entries []string
}

type Tag struct {
	Name string
	IDs  []int32
}

type TagGroup struct {
	Registry string
	Tags     []Tag
}

var (
	once  sync.Once
	regs  []Registry
	tags  []TagGroup
	index map[string]map[string]int32
)

func load() {
	zr, err := gzip.NewReader(bytes.NewReader(blob))
	if err != nil {
		panic("regsync: " + err.Error())
	}
	var d struct {
		Registries []Registry
		Tags       []TagGroup
	}
	if err := json.NewDecoder(zr).Decode(&d); err != nil {
		panic("regsync: " + err.Error())
	}
	regs, tags = d.Registries, d.Tags
	index = make(map[string]map[string]int32, len(regs))
	for _, r := range regs {
		m := make(map[string]int32, len(r.Entries))
		for i, e := range r.Entries {
			m[e] = int32(i)
		}
		index[r.Name] = m
	}
}

// Registries returns the synchronized registries in vanilla sync order.
// The result is shared and must not be modified.
func Registries() []Registry {
	once.Do(load)
	return regs
}

// Tags returns the network tags of every registry that has any.
// The result is shared and must not be modified.
func Tags() []TagGroup {
	once.Do(load)
	return tags
}

// Index returns the network ID of entry in a synchronized registry.
// Both names default to the minecraft namespace.
func Index(registry, entry string) (int32, bool) {
	once.Do(load)
	id, ok := index[qualify(registry)][qualify(entry)]
	return id, ok
}

func qualify(id string) string {
	if strings.IndexByte(id, ':') >= 0 {
		return id
	}
	return "minecraft:" + id
}
